package com.shivhub.backend.entity;
import java.math.BigDecimal; import java.time.*; import com.shivhub.backend.enums.MarketplaceListingStatus; import jakarta.persistence.*; import lombok.Data;
@Entity @Table(name="marketplace_listings", indexes={@Index(name="idx_market_listing_status_expiry",columnList="status,expires_at"),@Index(name="idx_market_listing_owner",columnList="owner_id")}) @Data
public class MarketplaceListing { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="owner_id",nullable=false) private User owner; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="category_id",nullable=false) private MarketplaceCategory category; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="subcategory_id") private MarketplaceSubcategory subcategory; @Column(nullable=false,length=180) private String title; @Column(nullable=false,columnDefinition="TEXT") private String description; @Column(nullable=false,precision=12,scale=2) private BigDecimal price; private boolean negotiable; @Column(name="item_condition",length=40) private String condition; private String brand; private String model; @Column(name="manufacture_year") private Integer year; @Column(name="usage_details",length=500) private String usage; @Column(columnDefinition="TEXT") private String location; private String city; private String district; private String state; @Column(name="contact_preference",length=40) private String contactPreference="INQUIRY"; @Column(name="attributes_json",columnDefinition="TEXT") private String attributesJson; @Column(name="listing_days",nullable=false) private int listingDays=10; @Enumerated(EnumType.STRING) @Column(nullable=false,length=35) private MarketplaceListingStatus status=MarketplaceListingStatus.DRAFT; @Column(name="rejection_reason",columnDefinition="TEXT") private String rejectionReason; @Column(name="expires_at") private LocalDateTime expiresAt; @Column(name="sold_at") private LocalDateTime soldAt; @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt; @Column(name="updated_at",nullable=false) private LocalDateTime updatedAt; @PrePersist void create(){createdAt=updatedAt=LocalDateTime.now();} @PreUpdate void update(){updatedAt=LocalDateTime.now();} }
